import { NextResponse } from "next/server";
import { createClient } from "@supabase/supabase-js";
import { z } from "zod";
import { SLOTS } from "@/lib/slots";

const Body = z.object({
  name: z.string().min(1).max(120),
  email: z.string().regex(/^[^@\s]+@berkeley\.edu$/i, "Please use your berkeley.edu address"),
  department: z.string().min(1).max(120),
  research: z.string().min(1).max(280),
  slots: z.array(z.enum(SLOTS.map((s) => s.id) as [string, ...string[]])).min(1).max(3),
});

export async function POST(req: Request) {
  const parsed = Body.safeParse(await req.json());
  if (!parsed.success) return NextResponse.json({ error: parsed.error.issues[0].message }, { status: 400 });
  const db = createClient(process.env.SUPABASE_URL!, process.env.SUPABASE_SERVICE_ROLE_KEY!);
  const { error } = await db.from("signups").insert({ ...parsed.data, created_at: new Date().toISOString() });
  if (error) return NextResponse.json({ error: "Could not save, try again" }, { status: 500 });
  return NextResponse.json({ ok: true });
}

"use client";
import { useState } from "react";
import { SLOTS } from "@/lib/slots";

const fmt = (iso: string) => new Date(iso).toLocaleString("en-US", { weekday: "short", month: "short", day: "numeric", hour: "numeric", minute: "2-digit" });

export default function Signup() {
  const [picked, setPicked] = useState<string[]>([]);
  const [msg, setMsg] = useState<string | null>(null);
  const toggle = (id: string) => setPicked((p) => (p.includes(id) ? p.filter((x) => x !== id) : p.length < 3 ? [...p, id] : p));
  async function submit(e: React.FormEvent<HTMLFormElement>) {
    e.preventDefault();
    const f = new FormData(e.currentTarget);
    const res = await fetch("/api/signup", { method: "POST", body: JSON.stringify({ ...Object.fromEntries(f), slots: picked }) });
    const j = await res.json();
    setMsg(res.ok ? "Thanks! We'll email you a calendar invite." : j.error);
  }
  return (
    <main className="page narrow">
      <h1>Sign up for a research chat</h1>
      <p className="lede">30 minutes about how you keep track of your research. Pick up to three times.</p>
      <form onSubmit={submit} className="stack">
        <input name="name" placeholder="Name" required />
        <input name="email" type="email" placeholder="you@berkeley.edu" required />
        <input name="department" placeholder="Department" required />
        <input name="research" placeholder="Your research in one line" maxLength={280} required />
        <fieldset className="slots">
          {SLOTS.map((s) => (
            <label key={s.id} className={picked.includes(s.id) ? "slot on" : "slot"}>
              <input type="checkbox" checked={picked.includes(s.id)} onChange={() => toggle(s.id)} /> {fmt(s.start)}
            </label>
          ))}
        </fieldset>
        <button type="submit" disabled={!picked.length}>Sign up</button>
        {msg && <p className="note">{msg}</p>}
      </form>
    </main>
  );
}
